#!/usr/bin/env bash
# Reproduce R5 lumpi-track submission 'r5' (model-lumpi-track/routed-g7): test-frame inference with the exact
# checkpoints, merge with the committed model.yaml, compare with the scored zip, repackage the same 50 frames, kit check.
# Generated by common/tools/reproduce_submission.py; scored zip model-lumpi-track/routed-g7/submissions/2026-10-14_r5/lumpi_r5_submission.zip (md5 ae3612bfa0607f3f0773702acd985fd0).
# Usage: CUDA_VISIBLE_DEVICES=0 bash model-lumpi-track/routed-g7/test/reproduce_r5.sh
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
OUT=model-lumpi-track/routed-g7/test/output/repro_r5
mkdir -p $OUT
# member cp_tta: model-lumpi-track/centerpoint-g1v3, checkpoint md5 25e4c0acf63d4b8f3b425fdc37bb3898
python common/tools/pcdet_predict.py model-lumpi-track/centerpoint-g1v3 --ckpt model-lumpi-track/centerpoint-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/centerpoint-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_cp_tta.json
# member g1: model-lumpi-track/pointpillars-g1, checkpoint md5 16e68b8b9142688967e4b3d006ac9d54
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1 --ckpt model-lumpi-track/pointpillars-g1/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-g1/test/postprocess.yaml --out $OUT/predictions_g1.json
# member g1v3: model-lumpi-track/pointpillars-g1v3, checkpoint md5 e403acdc3ae30a84de3989da34619440
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1v3 --ckpt model-lumpi-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-g1v3/test/postprocess.yaml --out $OUT/predictions_g1v3.json
# member g1v3_tta: model-lumpi-track/pointpillars-g1v3, checkpoint md5 e403acdc3ae30a84de3989da34619440
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1v3 --ckpt model-lumpi-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_g1v3_tta.json
# member pp4_tta: model-lumpi-track/pointpillars-g1v4, checkpoint md5 46e9f504fd05e90f72272387a102eeb0
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1v4 --ckpt model-lumpi-track/pointpillars-g1v4/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-g1v4/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_pp4_tta.json
# member ppros4_tta: model-lumpi-track/pointpillars-ros-g1v4, checkpoint md5 97be701cb39c8b56c663acee56cc7bf7
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-ros-g1v4 --ckpt model-lumpi-track/pointpillars-ros-g1v4/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-ros-g1v4/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_ppros4_tta.json
# member ppros_tta: model-lumpi-track/pointpillars-ros-g1v3, checkpoint md5 590e9f16fe22d1f429d4827392c1f0ba
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-ros-g1v3 --ckpt model-lumpi-track/pointpillars-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-ros-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_ppros_tta.json
# member pvros4_tta: model-lumpi-track/pvrcnnpp-ros-g1v4, checkpoint md5 3fffacf2d0baab79eb5cd12676ea591f
python common/tools/pcdet_predict.py model-lumpi-track/pvrcnnpp-ros-g1v4 --ckpt model-lumpi-track/pvrcnnpp-ros-g1v4/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pvrcnnpp-ros-g1v4/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_pvros4_tta.json
# member pvros_tta: model-lumpi-track/pvrcnnpp-ros-g1v3, checkpoint md5 66c1f05a2e602113dd011d96a22ec334
python common/tools/pcdet_predict.py model-lumpi-track/pvrcnnpp-ros-g1v3 --ckpt model-lumpi-track/pvrcnnpp-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pvrcnnpp-ros-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_pvros_tta.json
# member vrros4s2_tta: model-lumpi-track/voxelrcnn-ros-g1v4-s2, checkpoint md5 4d877e50e45311ece0284cca946d4e37
python common/tools/pcdet_predict.py model-lumpi-track/voxelrcnn-ros-g1v4-s2 --ckpt model-lumpi-track/voxelrcnn-ros-g1v4-s2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/voxelrcnn-ros-g1v4-s2/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_vrros4s2_tta.json
# member vrros_tta: model-lumpi-track/voxelrcnn-ros-g1v3, checkpoint md5 5415c1ceb113d8ca31fcac3ed2ba4a57
python common/tools/pcdet_predict.py model-lumpi-track/voxelrcnn-ros-g1v3 --ckpt model-lumpi-track/voxelrcnn-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/voxelrcnn-ros-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_vrros_tta.json
python common/tools/route_predictions.py merge model-lumpi-track/routed-g7 --pred cp_tta=$OUT/predictions_cp_tta.json --pred g1=$OUT/predictions_g1.json --pred g1v3=$OUT/predictions_g1v3.json --pred g1v3_tta=$OUT/predictions_g1v3_tta.json --pred pp4_tta=$OUT/predictions_pp4_tta.json --pred ppros4_tta=$OUT/predictions_ppros4_tta.json --pred ppros_tta=$OUT/predictions_ppros_tta.json --pred pvros4_tta=$OUT/predictions_pvros4_tta.json --pred pvros_tta=$OUT/predictions_pvros_tta.json --pred vrros4s2_tta=$OUT/predictions_vrros4s2_tta.json --pred vrros_tta=$OUT/predictions_vrros_tta.json --out $OUT/predictions.json
python common/tools/reproduce_submission.py model-lumpi-track/routed-g7 --tag r5 --compare $OUT/predictions.json
# the 50 realism frames: from the synthetic corpus when it is present (a check that it still gives the scored frames),
# else from the scored zip itself (a fresh clone has no corpus; the zip is in git)
if [ -d "$BDC_DATA/lumpi-track/pcdet/g1-v4/points" ]; then SYN=(--syn-split val --syn-list model-lumpi-track/routed-g7/submissions/2026-10-14_r5/synthetic_ids.txt); else SYN=(--syn-zip model-lumpi-track/routed-g7/submissions/2026-10-14_r5/lumpi_r5_submission.zip --syn-list model-lumpi-track/routed-g7/submissions/2026-10-14_r5/synthetic_ids.txt); fi
python common/tools/package_submission.py model-lumpi-track/routed-g7 --tag repro-r5 --pred $OUT/predictions.json --synthetic pcdet/g1-v4 "${SYN[@]}" --team ${BDC_TEAM:-KarmaRV} --ckpt 'reproduction of r5' --reproduction
Z=model-lumpi-track/routed-g7/test/output/repro-r5/submission.zip
python common/tools/check_submission.py --track lumpi $Z --official
python common/tools/reproduce_submission.py model-lumpi-track/routed-g7 --tag r5 --compare-zip $Z     # predictions and frames against the scored zip
